var PANELS = [
  {
    key: 'theta', letter: '(a)', caption: 'f(n) = \u0398(g(n))', hasUp: true, hasLo: true,
    upLabel: 'c\u2082g(n)', loLabel: 'c\u2081g(n)',
    popTitle: 'f(n) = \u0398(g(n))',
    popBody: 'Theta is a two-sided claim: there exist positive constants c\u2081, c\u2082 and a threshold n\u2080 such that c\u2081g(n) \u2264 f(n) \u2264 c\u2082g(n) for every n \u2265 n\u2080. The green corridor is the permitted region; nothing to the left of the dashed line matters. \u0398 is exactly O and \u03a9 holding at the same time.'
