}
function metrics(chart) {
  var ca = chart.chartArea;
  var W = ca.right - ca.left, H = ca.bottom - ca.top, s = Math.min(W, H);
  return {
    ca: ca, W: W, H: H, s: s,
    fs: clamp(s * 0.085, 8, 14),
    lw: clamp(s / 140, 1, 2.1),
    dot: clamp(s / 95, 1.2, 2.6)
  };
}
function haloText(ctx, txt, x, y, color, fs, align, italic) {
  ctx.font = (italic ? 'italic ' : '') + fs + 'px "Times New Roman", Georgia, serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#fff';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color;
  ctx.fillText(txt, x, y);
}

/* ---------- decorations plugin ---------- */
var decorPlugin = {
  id: 'decor',
  beforeDatasetsDraw: function (chart, args, opts) { drawShade(chart, opts.panel); },
  afterDatasetsDraw: function (chart, args, opts) {
