  var xa = xs.getPixelForValue(n0), xb = xs.getPixelForValue(NMAX);
  var poly;
  ctx.save();
  ctx.beginPath(); ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top); ctx.clip();
  if (p.key === 'theta') {
    poly = curvePixels(chart, upFn, n0, NMAX, 120).concat(curvePixels(chart, loFn, n0, NMAX, 120).reverse());
  } else if (p.key === 'O') {
    poly = curvePixels(chart, upFn, n0, NMAX, 120).concat([[xb, ca.bottom], [xa, ca.bottom]]);
  } else {
    poly = curvePixels(chart, loFn, n0, NMAX, 120).concat([[xb, ca.top], [xa, ca.top]]);
