  ctx.beginPath(); ctx.moveTo(x, ca.bottom - 3); ctx.lineTo(x, ca.bottom + 4); ctx.stroke();
  ctx.restore();
  haloText(ctx, 'n\u2080', x, ca.bottom + m.fs * 1.35, '#111', m.fs, 'center', true);
}

function drawAxisArrow(chart) {
  var m = metrics(chart), ctx = chart.ctx, ca = m.ca;
  var y = ca.bottom, x = ca.right;
  ctx.save();
  ctx.strokeStyle = '#000'; ctx.fillStyle = '#000'; ctx.lineWidth = 1;
