  items.push({ t: 'f(n)', c: BLACK, y: ys.getPixelForValue(fFn(nAt)) });
  if (p.hasLo) items.push({ t: p.loLabel, c: BLUE, y: ys.getPixelForValue(loFn(nAt)) });
  items.forEach(function (it) { it.y = clamp(it.y - m.fs * 0.55, ca.top + m.fs, ca.bottom - 2); });
  items.sort(function (a, b) { return a.y - b.y; });
