  var over = items[items.length - 1].y - (ca.bottom - 2);
  if (over > 0) for (i = 0; i < items.length; i++) items[i].y -= over;
  for (i = 0; i < items.length; i++) {
    haloText(ctx, items[i].t, ca.right - 2, Math.max(ca.top + m.fs, items[i].y), items[i].c, m.fs, 'right', true);
  }
