  for (i = 0; i <= m; i++) {
    n = a + (b - a) * i / m;
    pts.push([xs.getPixelForValue(n), ys.getPixelForValue(fn(n))]);
  }
  return pts;
}
function pathPoly(ctx, pts) {
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]); else ctx.lineTo(pts[i][0], pts[i][1]);
  }
  ctx.closePath();
}
function metrics(chart) {
  var ca = chart.chartArea;
  var W = ca.right - ca.left, H = ca.bottom - ca.top, s = Math.min(W, H);
  return {
    ca: ca, W: W, H: H, s: s,
    fs: clamp(s * 0.085, 8, 14),
    lw: clamp(s / 140, 1, 2.1),
    dot: clamp(s / 95, 1.2, 2.6)
