  { title: '\u0398 is both at once', n: 'Switch to \u0398. Now both constants matter: f(n) must stay inside the corridor between c\u2081g(n) and c\u2082g(n) past n\u2080. Squeeze either constant and the corridor closes until violations appear.', s: { view: '\u0398 (two-sided)', n0: 30, cU: 2, cL: 0.7 } },
  { title: 'Close the corridor', n: 'Push c\u2082 down and c\u2081 up. The green band narrows and f(n) pokes out on both sides — yet a wider pair of constants always exists, which is why f is still \u0398(g).', s: { view: '\u0398 (two-sided)', n0: 30, cU: 1.1, cL: 1 } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var st = STEPS[stepIdx];
  AState.view = st.s.view; AState.n0 = st.s.n0; AState.cU = st.s.cU; AState.cL = st.s.cL;
  document.getElementById('boundViewInput').value = st.s.view;
  document.getElementById('thresholdN0Input').value = st.s.n0;
  document.getElementById('thresholdN0Val').value = st.s.n0;
  document.getElementById('cUpperInput').value = st.s.cU;
  document.getElementById('cUpperVal').value = st.s.cU;
  document.getElementById('cLowerInput').value = st.s.cL;
  document.getElementById('cLowerVal').value = st.s.cL;
  document.getElementById('demoNarration').innerHTML =
    '<b>' + st.title + '</b><br>' + st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  updateAll();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

document.addEventListener('fig-resize', function () {
  charts.forEach(function (c) { c.resize(); });
});

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

