// @FIGURE_CODE_BEGIN
var INK = '#000', GHL = '#1f5fd0', RED = '#c62828', GREEN = 'rgba(120,190,120,0.18)';
var NMAX = 100, XMAX = 108, YMAX = 17;

var AState = { view: 'All three', n0: 25, cU: 2, cL: 0.7, hl: false };

/* flatter sigmoid g: plateau near the origin, gentle rise afterwards */
function gFn(n) { return 2.0 + 0.045 * n + 1.5 * Math.tanh((n - 35) / 20); }
/* f: pronounced dip-then-hump in the left fifth, then a gentle rise */
function fFn(n) {
  return 1.25 * gFn(n)
    + 3.6 * Math.exp(-Math.pow((n - 16) / 8, 2))
    - 1.1 * Math.exp(-Math.pow((n - 3) / 4.5, 2));
}
function upFn(n) { return AState.cU * gFn(n); }
function loFn(n) { return AState.cL * gFn(n); }

var PANELS = [
  {
    key: 'theta', letter: '(a)', caption: 'f(n) = \u0398(g(n))', hasUp: true, hasLo: true,
    upLabel: 'c\u2082g(n)', loLabel: 'c\u2081g(n)',
    popTitle: 'f(n) = \u0398(g(n))',
    popBody: 'Theta is a two-sided claim: there exist positive constants c\u2081, c\u2082 and a threshold n\u2080 with c\u2081g(n) \u2264 f(n) \u2264 c\u2082g(n) for every n \u2265 n\u2080. The tinted corridor is the permitted region; nothing to the left of the dashed line matters. \u0398 is exactly O and \u03a9 holding at once.'
  },
  {
    key: 'O', letter: '(b)', caption: 'f(n) = O(g(n))', hasUp: true, hasLo: false,
    upLabel: 'cg(n)', loLabel: null,
    popTitle: 'f(n) = O(g(n))',
    popBody: 'Big-O is a ceiling: some constant c and threshold n\u2080 exist with f(n) \u2264 cg(n) for all n \u2265 n\u2080. The size of c is irrelevant \u2014 only growth rates are being compared, so any finite prefix of bad behaviour is forgiven by moving n\u2080 to the right.'
  },
  {
    key: 'Omega', letter: '(c)', caption: 'f(n) = \u03a9(g(n))', hasUp: false, hasLo: true,
    upLabel: null, loLabel: 'cg(n)',
    popTitle: 'f(n) = \u03a9(g(n))',
    popBody: 'Big-Omega is a floor: some constant c and threshold n\u2080 exist with f(n) \u2265 cg(n) for all n \u2265 n\u2080. Shrinking c pushes the floor down until f clears it, which shows the statement is about growth rate, not about any particular multiplier.'
  }
];

var charts = [], wrappers = [];

var container = document.getElementById('container');
var row = document.createElement('div');
row.style.cssText = 'display:flex;width:100%;height:100%;gap:6px;';
container.appendChild(row);

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function gColor() { return AState.hl ? GHL : INK; }

function curvePixels(chart, fn, a, b, m) {
  var xs = chart.scales.x, ys = chart.scales.y, pts = [], i, n;
  for (i = 0; i <= m; i++) {
    n = a + (b - a) * i / m;
    pts.push([xs.getPixelForValue(n), ys.getPixelForValue(fn(n))]);
  }
  return pts;
}
function pathPoly(ctx, pts) {
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) {
    if (i === 0) ctx.moveTo(pts[i][0], pts[i][1]); else ctx.lineTo(pts[i][0], pts[i][1]);
  }
  ctx.closePath();
}
function metrics(chart) {
  var ca = chart.chartArea;
  var W = ca.right - ca.left, H = ca.bottom - ca.top, s = Math.min(W, H);
  return {
    ca: ca, W: W, H: H, s: s,
    fs: clamp(s * 0.075, 7.5, 13),
    lw: clamp(s / 200, 0.9, 1.5),
    dot: clamp(s / 110, 1.1, 2.3)
  };
}
function haloText(ctx, txt, x, y, color, fs, align, italic) {
  ctx.font = (italic ? 'italic ' : '') + fs.toFixed(1) + 'px "Times New Roman", Georgia, serif';
  ctx.textAlign = align || 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#fff';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color;
  ctx.fillText(txt, x, y);
}

/* ---------- decorations plugin ---------- */
var decorPlugin = {
  id: 'decor',
  beforeDatasetsDraw: function (chart, args, opts) { drawShade(chart, opts.panel); },
  afterDatasetsDraw: function (chart, args, opts) {
    drawViolations(chart, opts.panel);
    drawDashed(chart, opts.panel);
    drawAxisArrow(chart);
    drawCurveLabels(chart, opts.panel);
    drawCaptions(chart, opts.panel);
  }
};

/* permitted region: a band hugging the bounding curve, not a whole half-plane */
function drawShade(chart, p) {
  if (!AState.hl) return;
  var n0 = AState.n0; if (n0 >= NMAX) return;
  var ctx = chart.ctx, ca = chart.chartArea;
  var band = (ca.bottom - ca.top) * 0.20;
  var poly, i, mirrored;
  ctx.save();
  ctx.beginPath(); ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top); ctx.clip();
  if (p.key === 'theta') {
    poly = curvePixels(chart, upFn, n0, NMAX, 120)
      .concat(curvePixels(chart, loFn, n0, NMAX, 120).reverse());
  } else if (p.key === 'O') {
    var up = curvePixels(chart, upFn, n0, NMAX, 120);
    mirrored = [];
    for (i = up.length - 1; i >= 0; i--) mirrored.push([up[i][0], up[i][1] + band]);
    poly = up.concat(mirrored);
  } else {
    var lo = curvePixels(chart, loFn, n0, NMAX, 120);
    mirrored = [];
    for (i = lo.length - 1; i >= 0; i--) mirrored.push([lo[i][0], lo[i][1] - band]);
    poly = lo.concat(mirrored);
  }
  pathPoly(ctx, poly);
  ctx.fillStyle = GREEN; ctx.fill();
  ctx.restore();
}

function isViolating(p, n) {
  var fv = fFn(n);
  if (p.hasUp && fv > upFn(n) + 1e-9) return true;
  if (p.hasLo && fv < loFn(n) - 1e-9) return true;
  return false;
}

function drawViolations(chart, p) {
  var m = metrics(chart), ctx = chart.ctx, ca = m.ca;
  var xs = chart.scales.x, ys = chart.scales.y;
  var n0 = AState.n0, step = 0.4, run = [], n;
  ctx.save();
  ctx.beginPath(); ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top); ctx.clip();
  function flush(pts) {
    if (pts.length < 2) {
      if (pts.length === 1) {
        ctx.beginPath(); ctx.arc(pts[0][0], pts[0][1], m.dot, 0, 6.2832);
        ctx.fillStyle = RED; ctx.fill();
      }
      return;
    }
    ctx.beginPath();
    for (var i = 0; i < pts.length; i++) { i ? ctx.lineTo(pts[i][0], pts[i][1]) : ctx.moveTo(pts[i][0], pts[i][1]); }
    ctx.strokeStyle = RED; ctx.lineWidth = m.lw + 0.9; ctx.lineCap = 'round'; ctx.stroke();
    for (var j = 0; j < pts.length; j += 9) {
      ctx.beginPath(); ctx.arc(pts[j][0], pts[j][1], m.dot, 0, 6.2832);
      ctx.fillStyle = RED; ctx.fill();
    }
  }
  for (n = n0; n <= NMAX + 1e-6; n += step) {
    if (isViolating(p, n)) run.push([xs.getPixelForValue(n), ys.getPixelForValue(fFn(n))]);
    else { flush(run); run = []; }
  }
  flush(run);
  ctx.restore();
}

function drawDashed(chart, p) {
  var m = metrics(chart), ctx = chart.ctx, ca = m.ca;
  var xs = chart.scales.x, ys = chart.scales.y, n0 = AState.n0;
  var x = xs.getPixelForValue(n0);
  var tops = [ys.getPixelForValue(fFn(n0))];
  if (p.hasUp) tops.push(ys.getPixelForValue(upFn(n0)));
  if (p.hasLo) tops.push(ys.getPixelForValue(loFn(n0)));
  var yTop = clamp(Math.min.apply(null, tops), ca.top + 2, ca.bottom);
  ctx.save();
  ctx.setLineDash([4, 3]);
  ctx.strokeStyle = '#000'; ctx.lineWidth = 0.9;
  ctx.beginPath(); ctx.moveTo(x, ca.bottom); ctx.lineTo(x, yTop); ctx.stroke();
  ctx.setLineDash([]);
  ctx.beginPath(); ctx.moveTo(x, ca.bottom - 3); ctx.lineTo(x, ca.bottom + 3.5); ctx.stroke();
  ctx.restore();
  haloText(ctx, 'n\u2080', x, ca.bottom + m.fs * 1.25, '#000', m.fs, 'center', true);
}

function drawAxisArrow(chart) {
  var m = metrics(chart), ctx = chart.ctx, ca = m.ca;
  var y = ca.bottom, x = ca.right;
  var a = clamp(m.s / 40, 5, 9);
  ctx.save();
  ctx.strokeStyle = '#000'; ctx.fillStyle = '#000'; ctx.lineWidth = 0.9;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + a, y); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x + a + 5, y); ctx.lineTo(x + a - 1, y - 3); ctx.lineTo(x + a - 1, y + 3);
  ctx.closePath(); ctx.fill();
  ctx.restore();
  haloText(ctx, 'n', x + a + 7, y + m.fs * 0.42, '#000', m.fs, 'left', true);
}

function drawCurveLabels(chart, p) {
  var m = metrics(chart), ctx = chart.ctx, ca = m.ca, ys = chart.scales.y;
  if (m.fs < 7.8) return;
  var nAt = 99, items = [], gc = gColor();
  if (p.hasUp) items.push({ t: p.upLabel, c: gc, y: ys.getPixelForValue(upFn(nAt)) });
  items.push({ t: 'f(n)', c: INK, y: ys.getPixelForValue(fFn(nAt)) });
  if (p.hasLo) items.push({ t: p.loLabel, c: gc, y: ys.getPixelForValue(loFn(nAt)) });
  items.forEach(function (it) { it.y = clamp(it.y - m.fs * 0.5, ca.top + m.fs, ca.bottom - 2); });
  items.sort(function (a, b) { return a.y - b.y; });
  var gap = m.fs * 1.25, i;
  for (i = 1; i < items.length; i++) {
    if (items[i].y - items[i - 1].y < gap) items[i].y = items[i - 1].y + gap;
  }
  var over = items[items.length - 1].y - (ca.bottom - 2);
  if (over > 0) for (i = 0; i < items.length; i++) items[i].y -= over;
  for (i = 0; i < items.length; i++) {
    haloText(ctx, items[i].t, ca.right - 1, Math.max(ca.top + m.fs, items[i].y), items[i].c, m.fs, 'right', true);
  }
}

function drawCaptions(chart, p) {
  var m = metrics(chart), ctx = chart.ctx, ca = m.ca;
  var cx = (ca.left + ca.right) / 2;
  haloText(ctx, p.caption, cx, ca.bottom + m.fs * 2.45, '#000', m.fs * 1.02, 'center', true);
  haloText(ctx, p.letter, cx, ca.bottom + m.fs * 3.75, '#000', m.fs * 0.95, 'center', false);
}

/* ---------- build charts ---------- */
function series(fn) {
  var a = [], NS = 300, i, n;
  for (i = 0; i <= NS; i++) { n = NMAX * i / NS; a.push({ x: n, y: fn(n) }); }
  return a;
}

function applyPadding(ch) {
  var h = ch.canvas.clientHeight || 300, w = ch.canvas.clientWidth || 260;
  ch.options.layout.padding = {
    top: clamp(h * 0.05, 8, 20),
    right: clamp(w * 0.11, 20, 36),
    bottom: clamp(h * 0.19, 42, 64),
    left: 4
  };
}

PANELS.forEach(function (p) {
  var w = document.createElement('div');
  w.style.cssText = 'flex:1 1 0;min-width:0;height:100%;position:relative;transition:opacity .25s;';
  var cv = document.createElement('canvas');
  cv.style.cssText = 'width:100%;height:100%;display:block;cursor:pointer';
  w.appendChild(cv); row.appendChild(w); wrappers.push(w);

  var ds = [];
  ds.push({ label: 'f', data: series(fFn), borderColor: INK, borderWidth: 1.2, pointRadius: 0, tension: 0, order: 0, fill: false });
  if (p.hasUp) ds.push({ label: 'up', data: series(upFn), borderColor: INK, borderWidth: 1.2, pointRadius: 0, tension: 0, order: 1, fill: false });
  if (p.hasLo) ds.push({ label: 'lo', data: series(loFn), borderColor: INK, borderWidth: 1.2, pointRadius: 0, tension: 0, order: 1, fill: false });

  var ch = new Chart(cv.getContext('2d'), {
    type: 'line',
    data: { datasets: ds },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false, parsing: false, normalized: true,
      layout: { padding: { top: 12, right: 26, bottom: 52, left: 4 } },
      plugins: { legend: { display: false }, tooltip: { enabled: false }, decor: { panel: p } },
      scales: {
        x: {
          type: 'linear', min: 0, max: XMAX,
          grid: { display: false, drawTicks: false }, ticks: { display: false },
          border: { display: true, color: '#000', width: 1 }
        },
        y: {
          type: 'linear', min: 0, max: YMAX,
          grid: { display: false, drawTicks: false }, ticks: { display: false },
          border: { display: true, color: '#000', width: 1 }
        }
      }
    },
    plugins: [decorPlugin]
  });
  ch.$panel = p;
  charts.push(ch);

  cv.addEventListener('mousemove', function (ev) {
    var r = cv.getBoundingClientRect();
    var n = ch.scales.x.getValueForPixel(ev.clientX - r.left);
    if (!isFinite(n)) return;
    n = clamp(n, 0, NMAX);
    var txt = 'n \u2248 ' + n.toFixed(0) + '  \u00b7  f = ' + fFn(n).toFixed(2);
    if (p.hasUp) txt += '  \u00b7  ' + (p.key === 'theta' ? 'c\u2082g' : 'cg') + ' = ' + upFn(n).toFixed(2);
    if (p.hasLo) txt += '  \u00b7  ' + (p.key === 'theta' ? 'c\u2081g' : 'cg') + ' = ' + loFn(n).toFixed(2);
    txt += n < AState.n0 ? '  \u2014  left of n\u2080: ignored'
      : (isViolating(p, n) ? '  \u2014  outside the permitted region: bound violated' : '  \u2014  inside the permitted region');
    showTooltip(txt, ev);
  });
  cv.addEventListener('mouseleave', hideTooltip);
  cv.addEventListener('click', function () { showPopup(p.popTitle, p.popBody); });
});

/* ---------- update ---------- */
function panelActive(p) {
  var v = AState.view;
  if (v === 'All three') return true;
  if (v.charAt(0) === '\u0398') return p.key === 'theta';
  if (v.charAt(0) === 'O') return p.key === 'O';
  return p.key === 'Omega';
}

function updateAll() {
  var gc = gColor();
  charts.forEach(function (ch, i) {
    var p = PANELS[i];
    applyPadding(ch);
    ch.data.datasets.forEach(function (d) {
      if (d.label === 'up') { d.data = series(upFn); d.borderColor = gc; }
      else if (d.label === 'lo') { d.data = series(loFn); d.borderColor = gc; }
      else d.borderColor = INK;
    });
    if (ch.chartArea) {
      var m = metrics(ch);
      ch.data.datasets.forEach(function (d) { d.borderWidth = m.lw; });
    }
    ch.update('none');
    wrappers[i].style.opacity = panelActive(p) ? '1' : '0.32';
  });
}

function touched() { AState.hl = true; }
function set_boundView(v) { touched(); AState.view = v; updateAll(); }
function toggle_boundView(v) { set_boundView(v); }
function update_thresholdN0(v) { touched(); AState.n0 = v; updateAll(); }
function update_cUpper(v) { touched(); AState.cU = v; updateAll(); }
function update_cLower(v) { touched(); AState.cL = v; updateAll(); }
function resetFigure() { applyStep(0); }

/* ---------- demo player ---------- */
var STEPS = [
  { title: 'The textbook picture', n: 'Three panels, one function f(n) compared against scaled copies of the same g(n). In every panel the dashed line at n\u2080 marks where the promise begins; everything to its left is ignored. Hover a curve for values, click a panel for the definition.', s: { view: 'All three', n0: 25, cU: 2, cL: 0.7 }, hl: false },
  { title: 'Upper bound: f(n) = O(g(n))', n: 'Focus on the O panel. The tinted band hugging cg(n) is the permitted region \u2014 everything at or below the ceiling. Past n\u2080, f(n) never leaves it, and that is the entire content of big-O.', s: { view: 'O (upper)', n0: 25, cU: 2, cL: 0.7 }, hl: true },
  { title: 'Shrink c until the bound breaks', n: 'The upper constant drops to 0.8. The ceiling falls through f(n) and red violation marks appear to the right of n\u2080 \u2014 the bound fails only because c is too small, not because g grows too slowly.', s: { view: 'O (upper)', n0: 25, cU: 0.8, cL: 0.7 }, hl: true },
  { title: 'n\u2080 forgives the early chaos', n: "c is restored and n\u2080 slides back toward the origin. f(n)'s early hump now sticks out above the ceiling; sliding n\u2080 right makes it legal again \u2014 'eventually' is doing real work in the definition.", s: { view: 'O (upper)', n0: 6, cU: 2, cL: 0.7 }, hl: true },
  { title: 'Lower bound: f(n) = \u03a9(g(n))', n: 'Now the floor. With a small enough constant, cg(n) sits under f(n) for all n \u2265 n\u2080 \u2014 f grows at least as fast as g. Drag the lower constant up and watch the floor rise into the curve.', s: { view: '\u03a9 (lower)', n0: 25, cU: 2, cL: 0.7 }, hl: true },
  { title: '\u0398 is both at once', n: 'Switch to \u0398. Both constants matter now: f(n) must stay inside the corridor between c\u2081g(n) and c\u2082g(n) past n\u2080. \u0398 is exactly O and \u03a9 holding simultaneously.', s: { view: '\u0398 (two-sided)', n0: 25, cU: 2, cL: 0.7 }, hl: true },
  { title: 'Close the corridor', n: 'c\u2082 is pushed down and c\u2081 up. The band narrows and f(n) pokes out on both sides \u2014 yet a wider pair of constants always exists, which is why f is still \u0398(g). The claim is about a region, never about individual values.', s: { view: '\u0398 (two-sided)', n0: 25, cU: 1.1, cL: 1 }, hl: true }
];
var stepIdx = 0;

function applyStep(i) {
